public abstract class Context {public static final String ACTIVITY_SERVICE="activity",CONNECTIVITY_SERVICE="connectivity";public abstract File getFilesDir();public File getCacheDir(){return getFilesDir();} public abstract ContentResolver getContentResolver();public Context getApplicationContext(){return this;}public abstract PackageManager getPackageManager();public String getPackageName(){return "xyz.pocketui.fixture";}public ApplicationInfo getApplicationInfo(){return new ApplicationInfo();}public abstract Object getSystemService(String name);public <T>T getSystemService(Class<T> type){return type.cast(getSystemService(type.getName()));}public void startActivity(Intent i){throw new UnsupportedOperationException("Activity runtime");} }
